using System;using System.IO;using System.Text;using System.Threading;using System.Collections.Generic;using Windows.ApplicationModel.Calls;using Windows.Devices.Bluetooth;using Windows.Devices.Bluetooth.Rfcomm;using Windows.Devices.Enumeration;using Windows.Networking.Sockets;using Windows.Storage.Streams;using Windows.Foundation;
[assembly:System.Reflection.AssemblyFileVersion("0.1.0.35")]
static class HfpProbe {
 static StringBuilder log=new StringBuilder();static void Record(string s){log.AppendLine(s);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"hfp-probe.local.txt"),log.ToString());}
 static void Wait(IAsyncInfo op,int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);while(op.Status==AsyncStatus.Started&&DateTime.UtcNow<end)Thread.Sleep(20);if(op.Status==AsyncStatus.Started){op.Cancel();throw new TimeoutException("Bluetooth operation timed out");}if(op.Status!=AsyncStatus.Completed)throw new Exception("Bluetooth operation="+op.Status+";"+op.ErrorCode);}
 static T Get<T>(IAsyncOperation<T> op){Wait(op,10000);return op.GetResults();}
 static bool Busy(){return PhoneCallManager.IsCallActive||PhoneCallManager.IsCallIncoming;}
 static void Command(DataWriter w,DataReader r,string command){if(Busy())throw new Exception("Call detected: diagnostic stopped.");Record("TX="+command);w.WriteBytes(Encoding.ASCII.GetBytes(command+"\r"));var write=w.StoreAsync();Wait(write,3000);write.GetResults();var end=DateTime.UtcNow.AddSeconds(4);var buffer=new StringBuilder();while(DateTime.UtcNow<end){var read=r.LoadAsync(1024);Wait(read,4000);uint n=read.GetResults();if(n==0)throw new IOException("RFCOMM peer closed");string text=r.ReadString(n);buffer.Append(text);if(buffer.ToString().Contains("\r\nOK\r\n")||buffer.ToString().TrimEnd().EndsWith("OK")){Record("Reply=OK");return;}if(buffer.ToString().Contains("ERROR"))throw new IOException("HFP replied ERROR to "+command);}throw new TimeoutException("No HFP response");}
 static int Main(string[] args){var devices=new List<BluetoothDevice>();var services=new List<RfcommDeviceService>();try{if(Busy())throw new Exception("Active or incoming call: diagnostic not started.");var adapter=Get(BluetoothAdapter.GetDefaultAsync());if(adapter==null)throw new Exception("No Bluetooth adapter");Record("ClassicSupported="+adapter.IsClassicSupported+";LowEnergySupported="+adapter.IsLowEnergySupported);var radio=Get(adapter.GetRadioAsync());Record("Radio="+radio.State);var paired=Get(DeviceInformation.FindAllAsync(BluetoothDevice.GetDeviceSelectorFromPairingState(true)));Record("PairedDevices="+paired.Count);foreach(var info in paired){try{var device=Get(BluetoothDevice.FromIdAsync(info.Id));if(device==null)continue;devices.Add(device);Record("Device="+device.Name+";Connected="+device.ConnectionStatus);if(Array.IndexOf(args,"--status")>=0)continue;var result=Get(device.GetRfcommServicesForIdAsync(RfcommServiceId.FromUuid(new Guid("0000111f-0000-1000-8000-00805f9b34fb")),Array.IndexOf(args,"--cached")>=0?BluetoothCacheMode.Cached:BluetoothCacheMode.Uncached));Record("ServiceDiscovery="+result.Error+";Services="+result.Services.Count);foreach(var svc in result.Services)services.Add(svc);}catch(Exception ex){Record("DeviceSkipped="+ex.HResult.ToString("X8"));}}if(Array.IndexOf(args,"--status")>=0){Record("StatusOnly;No connection attempted");return 0;}Record("HfpGateways="+services.Count);foreach(var svc in services){try{var attrs=Get(svc.GetSdpRawAttributesAsync(BluetoothCacheMode.Cached));Record("SdpAttributeCount="+attrs.Count);if(attrs.ContainsKey(4)){using(var data=DataReader.FromBuffer(attrs[4])){var bytes=new byte[attrs[4].Length];data.ReadBytes(bytes);Record("SdpProtocolDescriptor="+BitConverter.ToString(bytes));}}}catch(Exception ex){Record("SdpReadError="+ex.HResult.ToString("X8"));}}if(services.Count!=1)throw new Exception("Expected exactly one paired HFP audio gateway.");using(var socket=new StreamSocket()){if(Busy())throw new Exception("Call detected before connection.");var connect=socket.ConnectAsync(services[0].ConnectionHostName,services[0].ConnectionServiceName,SocketProtectionLevel.BluetoothEncryptionWithAuthentication);Wait(connect,12000);connect.GetResults();Record("RFCOMM=Connected");using(var writer=new DataWriter(socket.OutputStream))using(var reader=new DataReader(socket.InputStream)){reader.InputStreamOptions=InputStreamOptions.Partial;Command(writer,reader,"AT+BRSF=32");Command(writer,reader,"AT+CIND=?");Command(writer,reader,"AT+CIND?");Command(writer,reader,"AT+CMER=3,0,0,1");writer.DetachStream();reader.DetachStream();}}Record("HFP=HandshakeComplete;No dial, answer, hangup or audio commands sent.");return 0;}catch(Exception e){Record("Error="+e.HResult.ToString("X8")+";"+e.Message);return 1;}finally{foreach(var svc in services)svc.Dispose();foreach(var device in devices)device.Dispose();Record("DiagnosticFinished");}}
}